const clamp = (n, a, b) => Math.max(a, Math.min(b, n));
const money = n => "$" + Math.round(n).toLocaleString("es-MX");
const fmt = (n, d = 0) => Number(n).toLocaleString("es-MX", { minimumFractionDigits: d, maximumFractionDigits: d });
const avg = l => { const v = l.filter(x => typeof x === "number"); return v.length ? v.reduce((a, b) => a + b, 0) / v.length : null; };

function bill(kwh) {
  const rows = TARIFF.blocks.map(b => { const k = clamp(kwh - b.from, 0, b.to - b.from); return { ...b, kwh: k, cost: k * b.price }; });
  const total = rows.reduce((s, r) => s + r.cost, 0) * (1 + TARIFF.iva);
  const dacTotal = (kwh * TARIFF.dacPrice + TARIFF.dacFixedMonthly * 2) * (1 + TARIFF.iva);
  return { rows, total, monthly: kwh / 2, dacTotal };
}
const lastPrice = kwh => { const b = TARIFF.blocks.find(x => kwh > x.from && kwh <= x.to) || TARIFF.blocks[0]; return b.price * (1 + TARIFF.iva); };
const appKwh = (a, q) => a.kwhDay ? a.kwhDay * q * 60 : a.watts * q * a.h * 60 / 1000;

const heat = t => `hsl(${50 - 50 * clamp(t, 0, 1)} 95% 62%)`;
const heatBg = t => {
  t = clamp(t, 0, 1);
  const h = 152 - 152 * t, s = 58 - 3 * t, l = 31 - 7 * t;
  const lightL = Math.min(95, l + 14), darkL = Math.max(5, l - 12);
  return `radial-gradient(130% 95% at 50% -10%, hsl(${h} ${s}% ${lightL}%) 0%, hsl(${h} ${s}% ${l}%) 45%, hsl(${h} ${s}% ${darkL}%) 100%)`;
};

function savings(kwh, apps) {
  const items = [];
  if (apps.refri_old) items.push(["un refri eficiente", (2.4 - 1.0) * 60 * apps.refri_old]);
  if (apps.inc) items.push(["focos LED", (60 - 9) * 5 * 60 / 1000 * apps.inc]);
  if (apps.shower) items.push(["calentador solar", 5000 * 0.4 * 60 / 1000 * apps.shower]);
  if (apps.heater) items.push(["sellar rendijas", 1500 * 2 * 60 / 1000 * 0.3 * apps.heater]);
  items.push(["apagar lo que está en espera", Math.max(8, kwh * 0.05)]);
  const k = Math.min(items.reduce((s, x) => s + x[1], 0), kwh * 0.8);
  const pesos = kwh > 0 ? bill(kwh).total - bill(kwh - k).total : 0;
  return { kwh: Math.round(k), pesos: Math.round(pesos), co2: Math.round(k * 6 * CO2_PER_KWH), from: items.map(x => x[0]) };
}

const PTS = {
  contrato: { propio: 100, comparte: 60, sin: 15 }, cortes: { nunca: 100, mes: 70, semana: 35, varias: 10 },
  recortes: { nunca: 100, alguna: 50, frecuente: 10 }, refri: { eficiente: 100, viejo: 45, no: 10 },
  luz: { led: 100, mezcla: 75, viejos: 45, poca: 15 }, cocina: { estufa: 100, lena: 35, sin: 10 },
  agua: { solar: 100, boiler: 85, regadera: 55, sin: 15 }
};
const pt = (k, v) => v == null ? null : PTS[k][v] ?? null;

const DIMS = [
  { id: "ase", n: "Asequibilidad", w: 0.3 }, { id: "acc", n: "Acceso", w: 0.25 },
  { id: "equ", n: "Equipamiento", w: 0.25 }, { id: "seg", n: "Seguridad", w: 0.2 }
];

function diagnose({ kwh, apps, answers: a, zone }) {
  const b = bill(kwh);
  const inc = INCOME.find(i => i.id === a.ingreso);
  let burden = null, bScore = null;
  if (inc && kwh > 0) {
    burden = (b.total / 2) / inc.mid * 100;
    bScore = burden <= 3 ? 100 : burden <= 6 ? 100 - (burden - 3) * 10 : burden <= 10 ? 70 - (burden - 6) * 8.75 : Math.max(5, 35 - (burden - 10) * 3);
  }
  const ase = avg([bScore, pt("recortes", a.recortes)]);
  const acc = a.contrato || a.cortes ? (pt("contrato", a.contrato) ?? 60) * 0.55 + (pt("cortes", a.cortes) ?? 70) * 0.45 : null;

  const refri = apps.refri_new > 0 ? "eficiente" : apps.refri_old > 0 ? "viejo" : "no";
  const luz = apps.led > 0 && apps.inc > 0 ? "mezcla" : apps.led > 0 ? "led" : apps.inc > 0 ? "viejos" : "poca";
  const h = Array.isArray(a.hogar) && a.hogar.length ? a.hogar : null;
  const cocina = h ? (h.includes("estufa") ? "estufa" : h.includes("lena") ? "lena" : "sin") : null;
  const agua = h && h.includes("solar") ? "solar" : h && h.includes("boiler") ? "boiler" : apps.shower > 0 ? "regadera" : h ? "sin" : null;
  const equ = avg([pt("refri", refri), pt("luz", luz), pt("cocina", cocina), pt("agua", agua)]);
  const nae = { "Refri eficiente": refri === "eficiente", "Estufa": cocina == null ? null : cocina === "estufa", "Agua caliente": agua == null ? null : agua !== "sin", "Iluminación": luz !== "poca" };

  const risks = (a.riesgos || []).filter(x => x !== "ninguna");
  let seg = a.riesgos && a.riesgos.length ? Math.max(0, 100 - risks.length * 22) : null;
  if (seg != null && a.contrato === "sin") seg = Math.min(seg, 60);
  const urgent = risks.includes("olor") || risks.includes("contactos");

  const scores = { ase, acc, equ, seg };
  let w = 0, t = 0;
  DIMS.forEach(d => { if (scores[d.id] != null) { w += d.w; t += scores[d.id] * d.w; } });
  const ibe = w ? Math.round(t / w) : null;

  const progs = [];
  const add = (id, why) => { if (!progs.find(p => p.id === id)) progs.push({ id, why, ...PROGRAMS[id] }); };
  if (refri !== "eficiente") add("fide", refri === "viejo" ? "Tu refri tiene más de 10 años." : "No registraste refrigerador.");
  if (apps.shower > 0 || agua === "sin" || agua === "boiler") {
    const why = apps.shower > 0 ? "Usas regadera eléctrica." : agua === "sin" ? "No tienes calentador de agua." : "Calientas el agua con gas.";
    add("solar", why);
  }
  if (burden != null && burden > 10) add("profeco", "La luz se lleva más del 10% de tu ingreso y no has podido resolverlo con tu proveedor.");

  add("lena", "Programa vigente, abierto a solicitud.");
  add("cosecha", "Programa vigente, abierto a solicitud.");
  add("locatel", "Pueden orientarte sobre apoyos para tu hogar.");

  return { ibe, level: levelFor(ibe), scores, burden, nae, urgent, progs, save: savings(kwh, apps), zone };
}

function levelFor(ibe) {
  if (ibe == null) return { label: "Faltan datos", msg: "Responde algunas preguntas del índice para calcularlo.", color: "#c8f1de" };
  if (ibe >= 80) return { label: "Bien iluminado", msg: "Tu hogar cubre bien sus necesidades de energía.", color: "#46d39a" };
  if (ibe >= 60) return { label: "Buena luz, con mejoras", msg: "Vas bien. Unos cambios te ahorran dinero y dan más comodidad.", color: "#ffcf3f" };
  if (ibe >= 40) return { label: "Luz a medias", msg: "Hay barreras de gasto o acceso que vale la pena atender.", color: "#ffb547" };
  return { label: "Necesitas apoyo", msg: "Tu hogar enfrenta varias carencias. Aquí tienes por dónde empezar.", color: "#ff6b6b" };
}

function summary(r) {
  return [
    r.ibe == null ? "Mi Índice de Bienestar Energético: faltan datos" : `Mi Índice de Bienestar Energético: ${r.ibe}/100 (${r.level.label})`,
    `Puedo ahorrar ${money(r.save.pesos)} y ${r.save.kwh} kWh cada bimestre.`,
    "Hecho con ENERGÍA CLARA · CDMX"
  ].join("\n");
}

const store = {
  get(k, d) { try { const v = localStorage.getItem("ec3_" + k); return v ? JSON.parse(v) : d; } catch (e) { return d; } },
  set(k, v) { try { localStorage.setItem("ec3_" + k, JSON.stringify(v)); } catch (e) { /* sin almacenamiento */ } }
};
function usePersist(key, init) {
  const [v, setV] = useState(() => store.get(key, init));
  useEffect(() => { store.set(key, v); }, [key, v]);
  return [v, setV];
}
const reduceMotion = () => { try { return window.matchMedia("(prefers-reduced-motion: reduce)").matches; } catch (e) { return false; } };

function Count({ to, dur = 900, f = v => fmt(v) }) {
  const [v, setV] = useState(0);
  const cur = useRef(0);
  useEffect(() => {
    if (reduceMotion()) { cur.current = to; setV(to); return; }
    const from = cur.current; let raf, t0;
    const tick = t => {
      if (!t0) t0 = t;
      const p = Math.min(1, (t - t0) / dur), e = 1 - Math.pow(1 - p, 4);
      cur.current = from + (to - from) * e; setV(cur.current);
      if (p < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [to]);
  return f(v);
}

